    (gen_random_uuid(), 'France Embassy in Uganda Opens Applications for Fully Funded Master’s Scholarships in France for 2026/2027 Academic Year', 'France Embassy in Uganda Opens Applications', 'scholarship', 'scholarship', null, null, 'The Embassy of France in Uganda has officially launched its call for applications for the 2026/2027 Master’s Degree Scholarship Programme, offering talented Ugandan graduates an opportunity to pursue postgraduate studies at recognized public universities in France. This prestigious scholarship program is aimed at young Ugandan students who already hold a Bachelor’s degree and wish to [&hellip;]', 'https://opportunitiesforyouth.org/2026/06/03/france-embassy-in-uganda-opens-applications-for-fully-funded-masters-scholarships-in-france-for-2026-2027-academic-year/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
