    (gen_random_uuid(), 'McCall MacBain Scholarship 2027 in Canada: Fully Funded Master&#8217;s Scholarship Covering Tuition, Fees, Living Stipend, Mentorship, and Leadership Development', 'McCall MacBain Scholarship', 'scholarship', 'scholarship', null, null, 'Students and graduates from around the world now have the opportunity to pursue graduate studies in Canada through the highly competitive McCall MacBain Scholarship 2027 at McGill University. This fully funded scholarship is designed to support future leaders who demonstrate exceptional character, community engagement, leadership potential, entrepreneurial spirit, and academic excellence. The McCa', 'https://opportunitiesforyouth.org/2026/06/02/apply-for-the-mccall-macbain-scholarships-at-mcgill-university-2026-cohort/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
    (gen_random_uuid(), 'SHE-CREEDS Intra-Africa Academic Mobility Scholarships 2026: Fully Funded MSc and PhD Opportunities for African Students in Climate-Responsive Agriculture, Energy-Efficient Technologies, and Digital Innovation', 'SHE-CREEDS Intra-Africa Academic Mobility Scholarships', 'scholarship', 'scholarship', null, null, 'African students seeking world-class postgraduate education, international academic exposure, and the opportunity to contribute to sustainable development now have an exceptional opportunity through the SHE-CREEDS Intra-Africa Academic Mobility Scholarships 2026. Co-funded by the European Union under the Intra-Africa Academic Mobility Scheme (NDICI-2024-MOBAF), the SHE-CREEDS project is offering f', 'https://opportunitiesforyouth.org/2026/06/01/she-creeds-intra-africa-academic-mobility-scholarships-2026-fully-funded-msc-and-phd-opportunities-for-african-students-in-climate-responsive-agriculture-energy-efficient-technologies-and-digital-i/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
    (gen_random_uuid(), 'FCDO Senior Research Fellowships 2027: Fully Funded Two-Year Fellowship Opportunities Across 11 Global Research Areas', 'FCDO Senior Research Fellowships', 'scholarship', 'scholarship', null, null, 'The Foreign, Commonwealth and Development Office (FCDO), through the Global Research and Technology Development (GRTD) Research Commissioning Centre (RCC), has officially opened applications for eleven prestigious Senior Research Fellowships for 2027. These fellowships are designed to connect leading academic researchers with UK government policymaking and international development initiatives. Th', 'https://opportunitiesforyouth.org/2026/06/01/fcdo-senior-research-fellowships-2027-fully-funded-two-year-fellowship-opportunities-across-11-global-research-areas/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
    (gen_random_uuid(), 'DAAD Helmut-Schmidt-Programme 2027 in Germany: Fully Funded Master’s Scholarships for Future Leaders in Public Policy and Good Governance', 'DAAD Helmut-Schmidt-Programme', 'scholarship', 'scholarship', null, null, 'The DAAD Helmut-Schmidt-Programme 2027, also known as the Master’s Scholarships for Public Policy and Good Governance (PPGG), is now open for applications. Funded by the German Federal Foreign Office, this prestigious fully funded scholarship programme supports talented future leaders from developing and emerging countries who are committed to advancing democracy, social justice, good governance, ', 'https://opportunitiesforyouth.org/2026/06/01/daad-helmut-schmidt-programme-masters-scholarships-for-public-policy-and-good-governance-2025/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
    (gen_random_uuid(), 'New Futures Mobility Fund 2026: Comprehensive Guide for Applicants in Australia', 'New Futures Mobility Fund', 'grant', 'grant', null, null, 'The New Futures Mobility Fund, delivered by the Australian Academy of Science, is a major national initiative designed to empower humanitarian visa holders living in Australia by supporting their participation in recognised scientific conferences, symposia, workshops, and other STEM‑focused professional events across the country. This program removes financial barriers, strengthens research visibi', 'https://opportunitiesforyouth.org/2026/06/05/new-futures-mobility-fund-2026-comprehensive-guide-for-applicants-in-australia/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
