    (gen_random_uuid(), 'BIRN Reporting Democracy Grant 2026: €1,500 Funding for Journalists Investigating Key Democracy Issues Across Central and Southeast Europe', 'BIRN Reporting Democracy Grant', 'grant', 'grant', null, null, 'Journalists across Central and Southeast Europe now have an exciting opportunity to secure funding for impactful reporting projects through the BIRN Reporting Democracy Grant 2026. The grant program is inviting professional freelance journalists, staff journalists, and reporting teams from the Visegrad and Balkan regions to submit proposals for investigative, analytical, or feature stories that ex', 'https://opportunitiesforyouth.org/2026/06/02/birn-reporting-democracy-grant-2026-e1500-funding-for-journalists-investigating-key-democracy-issues-across-central-and-southeast-europe/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
    (gen_random_uuid(), 'Disability Rights Fund 2026 Grant Round for Sub-Saharan Africa: Funding Opportunities for Organizations of Persons with Disabilities', 'Disability Rights Fund', 'grant', 'grant', null, null, 'Organizations of Persons with Disabilities (OPDs) across Sub-Saharan Africa often face significant challenges in securing sustainable funding for their advocacy, policy work, and community-driven initiatives. Many OPDs rely heavily on volunteer commitment and grassroots support to advance disability rights, making access to dedicated funding both essential and transformative. One of the most signi', 'https://opportunitiesforyouth.org/2026/06/02/disability-rights-fund-2026-grant-round-for-sub-saharan-africa-funding-opportunities-for-organizations-of-persons-with-disabilities/', 'opportunitiesforyouth.org, 2026', 'draft', now(), now()),
